package com.example.crackcs.evaluation.retrieval.benchmark;

import java.util.List;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;

/** Test-only bridge from stable evidence spans to IDs generated by the real database. */
final class ReferenceChunkMapping {
    record Evidence(String key, int start, int end, String content) {}
    record StoredChunk(long documentId, long chunkId, int start, int end, String content) {}

    static Map<String, Set<Long>> connect(long documentId, String source,
                                         List<Evidence> evidence, List<StoredChunk> chunks) {
        List<StoredChunk> ordered = chunks.stream()
                .filter(chunk -> chunk.documentId() == documentId)
                .sorted(Comparator.comparingInt(StoredChunk::start)).toList();
        for (StoredChunk chunk : ordered) {
            requireSource(source, chunk.start(), chunk.end(), chunk.content());
        }
        Map<String, Set<Long>> mapping = new LinkedHashMap<>();
        for (Evidence span : evidence) {
            requireSource(source, span.start(), span.end(), span.content());
            if (mapping.containsKey(span.key())) {
                throw new IllegalArgumentException("Duplicate evidence key: " + span.key());
            }
            int coveredUntil = span.start();
            Set<Long> ids = new LinkedHashSet<>();
            for (StoredChunk chunk : ordered) {
                if (chunk.end() <= span.start() || chunk.start() >= span.end()) {
                    continue;
                }
                if (chunk.start() > coveredUntil) {
                    throw new IllegalArgumentException("Uncovered evidence: " + span.key());
                }
                coveredUntil = Math.max(coveredUntil, chunk.end());
                ids.add(chunk.chunkId());
            }
            if (coveredUntil < span.end()) {
                throw new IllegalArgumentException("Uncovered evidence: " + span.key());
            }
            mapping.put(span.key(), Set.copyOf(ids));
        }
        return Map.copyOf(mapping);
    }

    private static void requireSource(String source, int start, int end, String content) {
        if (start < 0 || end <= start || end > source.length()
                || !source.substring(start, end).equals(content)) {
            throw new IllegalArgumentException("Evidence or chunk differs from source offsets");
        }
    }
}
